    const url = new URL(path, 'http://localhost')
    if (url.pathname === '/api/work-items') {
      const page = pages[Number(offsetOf(path)) / 2] ?? []
      return { ok: true, status: 200, json: async () => ({ items: page, total: 5, limit: 2, offset: Number(offsetOf(path)) }) }
