import { afterEach, describe, expect, it, vi } from 'vitest'
import { cleanup, fireEvent, render, screen, within } from '@testing-library/react'
import App from './App'
import type { Source, WorkItem } from './api'

afterEach(() => { cleanup(); vi.unstubAllGlobals() })

const item = (id: string, title: string): WorkItem => ({
  id, title, summary: null, status: 'pending', source_kind: 'outlook_email',
  source_external_id: `outlook_email:${id}`, source_url: null, assigned_agent: null,
  due_at: null, created_at: '', updated_at: '',
})
const src = (id: string, ext: string, subject: string): Source => ({
  id, kind: 'outlook_email', external_id: ext, subject, url: null, excerpt: null, observed_at: '',
})

describe('MANAGER PROBE', () => {
  it('zzmgr promote on a fully loaded queue must not resurrect Load more', async () => {
    // Queue is FULLY loaded: total 2, both items on page 1. No Load more should ever show.
    const page1 = [item('a', 'First item'), item('b', 'Second item')]
    const promoted = item('p', 'Promoted item')
    const calls: string[] = []
    const fetchMock = vi.fn(async (path: string, init?: RequestInit) => {
      const url = new URL(String(path), 'http://localhost')
      if (url.pathname === '/api/work-items') {
        calls.push(String(path))
        const offset = Number(url.searchParams.get('offset') ?? '0')
        // Server sorts updated_at desc; after promotion the new row is at offset 0,
        // so offset=2 now returns what used to be at index 1 — an already-loaded row.
        const all = calls.length > 1 ? [promoted, ...page1] : page1
        return { ok: true, status: 200, json: async () => ({ items: all.slice(offset, offset + 50), total: all.length, limit: 50, offset }) }
      }
      if (url.pathname === '/api/session') return { ok: true, status: 200, json: async () => ({ csrf_token: 'csrf-test' }) }
      if (url.pathname === '/api/sources') return { ok: true, status: 200, json: async () => ({ items: [src('s1', 'outlook_email:missed', 'A missed source')], total: 1, limit: 200, offset: 0 }) }
      if (url.pathname.endsWith('/promote')) return { ok: true, status: 201, json: async () => promoted }
      return { ok: true, status: 200, json: async () => ({ status: 'ok', service: 'workboard' }) }
    })
    vi.stubGlobal('fetch', fetchMock)
    render(<App />)
    const queue = await screen.findByRole('region', { name: 'Work queue' })
    await within(queue).findByText('First item')
    // precondition: everything is loaded, so no Load more
    expect(within(queue).queryByRole('button', { name: 'Load more' })).toBeNull()

    fireEvent.click(await screen.findByRole('button', { name: 'Promote' }))
    await within(queue).findByText('Promoted item')

    const resurrected = within(queue).queryByRole('button', { name: 'Load more' })
    console.log('AFTER PROMOTE — Load more:', resurrected ? 'SHOWN' : 'absent')
    if (resurrected) {
      fireEvent.click(resurrected)
      await new Promise(r => setTimeout(r, 50))
      console.log('work-item calls:', JSON.stringify(calls))
      console.log('"Second item" rendered count:', within(queue).queryAllByText('Second item').length)
    }
    expect(resurrected).toBeNull()
  })
})
EOF
